var render = function render() {
  var _vm = this,
    _c = _vm._self._c
  return _c(
    "ContentSlotsDistributor",
    { attrs: { "slot-key": _vm.$parent.slotKey } },
    [
      _c("p", [
        _vm._v(
          "虚无主义，作为怀疑主义的极致形式，在当下物质生活优越（至少比人类过去任何一个时刻都优越）的今天，以日常生活中只要稍加思考就能发现的荒诞现实以及网络的快速发展为土壤扎根，在年轻一代人中开始流行。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "虚无主义者一般认为任何事物都是无意义无价值的，所谓信仰，道德，都是虚假的，即 “上帝已死“。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "伴随着这种观念，人生变成了一个充满折磨的地狱，因为人是需要目的性来支撑自己的行为的，而虚无主义把这目的性给否定掉了，人随即变成了一具漫无目的的行尸走肉，不知道自己为何而活，更加难以感受到快乐，只能以过度纵欲作为发泄浑然度日。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "作为对人类本身的终极否定，这种观念在大多数地区被公认为是错误的。由此引申出来的思考，便是我今天的文章想要探讨的内容。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [_c("strong", [_vm._v("1.虚无主义，到底是对是错")])]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "虚无主义的核心是世界毫无意义，只有死亡能终结这无趣的一切，让我休息吧，停止我的思考吧。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "我们的本能中被深深刻上了对求生的本能，对死亡的恐惧，因此，在面对虚无主义这样的思想时，当然也会因为本能而排斥，毕竟这确实是反人类的，它竟然企图以逻辑推理的方式叫我去死，这能对吗？"
        ),
      ]),
      _vm._v(" "),
      _c("p", [_vm._v("这当然不能，简直就是一泡屎，是世界上最恶毒的东西!")]),
      _vm._v(" "),
      _c("p", [
        _vm._v("可如果我们抽离出自己的灵魂，脱离掉自己作为人的身份之后呢？"),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "我接下来的言论不是在给恐怖分子开脱，而是有时候有些正确的东西，可能它就是反人类的，让人难以接受的，你作为一个人，是无法轻易接受自己的死亡的，自然无法轻易接受虚无主义这样的思想，但是你不能因为自己无法接受，就找各种理由试图掩盖真相，就像哥白尼的日心说，在当时这无疑是反人类的，挑战教皇权威，这不就是在否认我们存在的意义吗？"
        ),
      ]),
      _vm._v(" "),
      _c("p", [_vm._v("异端邪教，必须杀之。")]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "可是，真理不会因为你的身份就迁就你什么，太阳确实就在太阳系的中心。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "而虚无主义的真理就是我们的存在是随机的，我们活着其实没有任何意义。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "真相就是我们活着仅仅是因为活着，因为深刻的动物本能让我们不敢寻求死亡，仅此而已。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "在现代艺术作品的探讨中，很多前卫作品已经不再避讳去探讨虚无主义，而是放开的讨论这一思想，其中作为代表的如瑞克和莫蒂，深刻探讨了在虚无主义之下人到底应该生活。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v("生命的本质到底是怎样，那么接下来就是我们文章的第二部分"),
      ]),
      _vm._v(" "),
      _c("p", [_c("strong", [_vm._v("2.生活的本质")])]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "如果你对虚无主义有所了解，那么你应该会知道，很多人都对虚无主义给出了自己的答案，如存在主义，或者是以家庭为中心来生活，放大人与人之间的羁绊，感情。\n为了更好的让你能够理解文章内容，接下来，我会引入一个新的概念，人的二分。\n将一个人分开，一部分是先天就带有的本能，代表人的局限性的一面，一部分是能够理性思考，代表人的超越性的一面。\n理性思考受制于本能局限。\n我的理解是绝对理性对于人而言能带来的只有负面的东西，想要活下去唯一能做的就是不思考意义，沉沦于自己人的身份，也就是本能的部分，让世俗感情来支配自己让身体的化学反应充斥你，像个动物一样，不去真正的思考意义，而是靠本能给予的一切来活着。\n绝对的理性可以解构一切。\n痛苦就是一种我们作为人自带的感情和理性的残酷的对冲。\n绝对的理性实际上脱离了人，所以很多结果对于人而言是难以接受的，比如虚无主义的思想，但我们是生物，这种宿命是无法逃离的。\n从前人们总认为真理一定是美的，和谐的，现在看来，也许对人而言可能也是残忍的。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [_c("strong", [_vm._v("3.将人作出分类")])]),
      _vm._v(" "),
      _c("p", [_vm._v("经过前面的铺垫 我们可以大致把人分为两类，")]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "第一类是依靠本能生活，包括依靠家庭，社会，各种世俗感情来生活的人。他们把本能的一面放大了，靠着身体的信号作为生存意志，不去时刻思考意义而是沉浸于物质世界的体验，类似存在主义、享乐主义、所谓乐观虚无主义等都属于这个分类。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "第二类是不断的思考，得出世界没有意义这个结论后，沉浸于虚无主义的怀抱，对活着失去兴趣的人。他们无法忍受自己去接受本能的支配，以理性作为首要来生活，能够体验的感情更少，更加厌世。主要生活在抽象世界之中。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "那么， 到底是要听从自己脑海中理性声音的选择，还是不让自己思考，继续像动物一样活着呢，实际上，我认为，如果神存在，那么第二类人是最接近神的，他们丢掉了本能的束缚，仅剩客观的思维来感知世界。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "写这篇文章，满足创作欲的同时也意在与读者进行交流，如若文章中出现逻辑错误或者能够更好的进行总结，恳求各位能够指出不足之处，涉世未深，有些想法可能比较幼稚，毕竟作者年龄尚小，且经过的系统性学习不多，几近于无，我本身受困虚无主义多年，因为一些原因也无法去追求依靠本能的生活，在网上看过很多人的解读，始终找不到满意的答案，在生与死之间徘徊。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "维特根斯坦在《哲学研究》里有这样一个观点，语言是摹画，不是逻辑。通俗来讲，一个语言名称（比如说虚无主义）解释它的最好方法是举例子，而不是逻辑推理。\n比如，小明整天很消极，经常说一些人生无意义的话，爱看叔本华。我们说小明是虚无主义。这是对虚无主义这个语言名称最好的解释。\n而换另一种说法：虚无主义本质上是怀疑主义，虚无主义本质上是无目的性，虚无主义本质上是价值丧失。这是一种唯实论的语言观，虽然用了本质一词，但是这三者对这个名称的本质言说，都只是一种阐释而已。\n维特根斯坦不仅反对上述，语言在逻辑上的实存，也反对语言在物质（物质还原论），和纯粹心灵（潜意识）上的实存。\n维特根斯坦还有一些观点，比如说“语言游戏”“家族类似”等等，从形而上或逻辑推演回到语言本身进行反思，可以多方面医治“哲学病”"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "有时宁愿自己没想过这些，没开过这个口子，也就没后来这些事，不够真的选择让自己一辈子蒙在鼓里不知真相，好像也不能接受。不过那些一辈子都没有仔细思考过这些问题的人，似乎也不会觉得自己被蒙在鼓里。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "恭喜你，首先你拥有了自己的思考——这是大多数人不具有的。\n其次，我也深陷虚无主义很久了，我也一直在想既然事物最终都将陷入虚无不复存在，那我的意义是什么，后来我看到了一幅漫画，上面内容大概是这样的：一个孩子（像你一样陷入了虚无主义）问他的妈妈：既然我们都会死，那我存在的意义是什么。\n妈妈回答道：你会因为甜甜圈吃了就没有了就不会去吃它吗?\n孩子说：不会。\n妈妈又说：人生就像甜甜圈一样，这还是逼着你吃的，不吃还不行，既然如此，那为什么不好好的品尝甜甜圈的味道呢？\n我读了这个漫画后，惊为天人，以为自己摆脱了虚无主义，但实际上并没有。\n我认为好好品尝甜甜圈这是一种逃避的做法，这会使我回到对周围的一切习以为常的情况——标志着我会浑浑噩噩地度过一生。\n后来我认了，这是虚无主义在我灵魂留下的标记，从此之后我就在生与死，善良与罪恶来回挣扎，自暴自弃，后来我身边就没有一个人了，就只剩我一个人和我的抽象世界，那时我才明白，我是人不是神，我需要现实。\n于是我开始做出改变，直到现在我有很多朋友，但我觉得我和他们格格不入，可能还是因为虚无主义的缘故吧（笑），但我还是像个正常人一样和他们相处，和他们一起开怀大笑，虽然我不知道是不是发自内心的笑，但可以肯定的是，我笑了。\n最后我才明白那幅漫画的真正含义。\nps.我管这个世界最后会不会陷入虚无，我开心了就行，虽然这只是稍微好一点的自暴自弃，但还是有效的。\n这并不会影响我对于周围的一切的好奇，并不会影响我对于虚无的思考和哲学的思考，相反，因为我与现实有了联系，我才不会惧怕虚无。\n什么？你说后来啊，后来我就从心底蔑视这个世界然后得了社交NB症。\n虚无主义是真的刻在了我的灵魂里，时至今日我依然会时不时的觉得很没意义想自杀，然后马上打开游戏让自己看一看自己的排名，然后就觉得还有这么多人在我前面，不行啊这，于是又觉得自己有意义了。\n挺荒唐的对吧，但这个世界也是有各种荒唐组成的。\n希望我的经历能对你有所帮助，祝你早日走出虚无主义，天将降大任于斯人也，必先苦其心志，劳其筋骨，饿其体肤，空乏其身，行拂乱其所为，所以动心忍性，曾益其所不能。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "1现代社会是一个工具理性主导的社会，人的精神价值被排除在外。\n2科学主义一直给我们打了个包票，承诺给我们一个终极真相，人们期待着这样一个承诺，实际往往是落空。人很自然就陷入虚无主义。\n3通过批判理性，很容易走上浪漫主义（存在主义，唯意志论，神秘主义，心理学技术）的路子，但是浪漫主义给出的方案也很难在现实生活中实践。\n4解决方案：维特根斯坦语言哲学。通过对语言的反思，解决日常生活里的哲学病，重新回归理性。\n4.1例如，语言指物论和物质还原论的哲学病：人生意义是什么，幸福是什么，快乐是什么，爱情是什么？一种哲学病的思路：爱情是神经递质分泌产生的快感。这很容易产生一种决定论的世界观，从而陷入虚无主义。\n5虚无主义实际上是一套理论浓度极高的观念，维特根斯坦语言哲学是一种反理论反本质的思路，通过学习，或许能对你有些帮助。\n我学得非常业余，如果有一些独断的说法，请指正和见谅"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "粗浅读过《存在主义是一种人道主义》，我认为萨特的观点还是很有借鉴意义和现实意义的。加缪的书读过几本，他的《西西弗神话》中的核心思想用来对抗抑郁症之类的心境障很有效。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "浪漫主义的方案都能很快的帮助抑郁症患者脱离困境，但是我觉得浪漫主义包括存在主义都过于关注人的主观能动性。在抑郁症患者不改变自己比较单一的世界观下（认为客观环境是无望的），实践是很难取得他预期的成效的，最后又会落回虚无主义，或者转变为享乐主义，功利主义，这些我觉得是比较糟糕的。但是这些也只是我自己和我身边人的例子，还比较缺乏实际经验"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "首先你得清楚一件事情，人的认知是有限的，如果你妄图完整的了解这个世界是不可能的。在康德的《纯粹理性批判》中的观点，我觉得是可以帮你解决疑虑的。就单纯的从这本书的译名中即可初见端倪，以一种纯粹理性不挟杂感情的方式去探究每个事情的意义是不切实际的，以这种方式探知这个世界如同盲人摸象。我觉得所谓虚无主义是一种认知陷阱，是在不断积累的知识经验自我怀疑的必经之路，如果想要逾越此沟堑，仍需要不断学习思考，才能达到下个境界。最后我希望你能明白下面两句话的真正含义“世界上只存在一种英雄主义，那就是在认清生活真相之后依然热爱生活”“看山不是山，看水不是水。看山还是山，看水还是水。”"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "要是虚无主义的起初是提出人理解错了老师的意思，你会怎么想？\n很多的哲学家就是在听认身体的指令想得又得不到，产生了苦的感觉，然后与这个词产生了共情。\n尼采说每个空度的日子都是对生命的辜负。他的思考有些部分是对的，但是在后来想用意识发挥出超人的状态，那是用虚妄去达虚妄。而找到本我才是超越平常的途径，这却得用理性思维了。\n至于理性思维的痛苦，比如用知止而后有定等方式看是可以脱离痛苦本身来思考的。你现在就是知止的一步。试试看看思想本源的书呢，人近几千年没变的就是对痛苦的感受。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "我也思考过这些问题，我高中的时候也陷入过虚无主义，说的简单一点，反正一切都没有意义，那干脆摆烂咯，随心所欲地活着就好了。\n后来上了大学觉得，这个世界应该没有这么简单，我不应该就停留在这个层面。后来我又发现，对意义的追求应该是我们生物的本能，像答主文章里面说的，我们无法逃离生物的本能。但是我又想，虽然生活是没有终极意义的，但是我们可以学着去享受生活的这个过程呀。就像在一个开放世界游戏里面，做一些想做的事，体验这个世界的游戏内容，毕竟已经进入了这个游戏，那干脆玩一玩。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "对于这个世界本质的思考，我觉得可以先不要盖棺定论，我感觉接触到虚无主义这个概念只是对世界认识的开始，还有很多哲学思想我都还没有了解过，我觉得得等我多读点书再来好好思考一下，可能就会有不一样的认识。\n我建议答主，如果可以的话，把这个问题先放一放，因为在知识和经历都比较有限的背景下思考，是会有很大局限性的，你说受困虚无主义已久，那我觉得你应该继续思考下去也想不出什么好办法了，所以先尽量去好好生活一段时间，这并不是向人性妥协，是去充实自己羸弱的意志，去丰富自己的精神世界，才能有更好的状态去思考。说不定就山穷水复疑无路，柳暗花明又一村了。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "虚无主义对接触者的影响在于真相和自身是矛盾的。或许他的意识他的一切都建立于热爱生活之上，可生活无意义，这就是矛盾。\n存在主义说，你不管怎么生活都是一样的，有时这比虚无主义更虚无主义。他并不否认你杀死亲人（举例）的行为"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
          "不知这么说能否使你更轻松，你应该去相信你所经历的痛苦其他人有非常大的概率也以不同形式经历过。而他们还活着，他们熬过了这种痛苦并且在之后没有那么痛苦了。由于人通常会隐藏自己并不快乐的一面，所以你看不到，（轻易）问不出，但这是真的。活在恐惧、焦率中是一件很普遍的事，你或许可以轻易找到现在就比你还要痛苦的人。"
        ),
      ]),
      _vm._v(" "),
      _c("p", [
        _vm._v(
